import type { Metadata } from "next";
import { site } from "@/content/site";

/** Static share image generated by `npm run icons` (src/app/opengraph-image.jpg, 1200×630). */
const shareImage = {
  url: "/opengraph-image.jpg",
  width: 1200,
  height: 630,
  alt: "Castellana Automobile AG – Automobile Leidenschaft seit 1983, Thalwil am Zürichsee",
};

/**
 * Per-page metadata incl. Open Graph/Twitter.
 *
 * Why: a page that sets its own `openGraph` replaces the layout's object completely —
 * including the file-based share image. Without per-page `openGraph`, every sub-page
 * inherits the home page's og:title and og:url. This helper sets both correctly.
 *
 *   export const metadata = pageMetadata({ title: "Kontakt & Anfahrt", description: "…", path: "/kontakt/" });
 */
export function pageMetadata({
  title,
  description,
  path,
  robots,
}: {
  title: string;
  description: string;
  /** Canonical path with trailing slash, e.g. "/kontakt/" */
  path: string;
  robots?: Metadata["robots"];
}): Metadata {
  const fullTitle = `${title} | ${site.name}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "de_CH",
      siteName: site.name,
      url: path,
      title: fullTitle,
      description,
      images: [shareImage],
    },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [shareImage] },
    ...(robots ? { robots } : {}),
  };
}
